for name,a,b in [('FWD',f1,f2),('REV',r1,r2)]:
 prediction=np.interp(b[:,0],a[:,0],a[:,1],period=360)
 error=b[:,1]-prediction
 print(name,'periodic interpolation correlation',np.corrcoef(prediction,b[:,1])[0,1],'RMS electric deg',np.sqrt(np.mean(error**2)),'max abs electric deg',max(abs(error)))
print('Mean zero difference electrical deg',np.rad2deg(5.118509-5.088051),'mechanical equivalent',np.rad2deg(5.118509-5.088051)/7)
print('Run2 direction gap interior mechanical mean',np.mean((r2[::-1,1]-f2[:,1])/7))
# Cross-validation: shared position model + direction-specific constant.
def features(a,d,k):
 t=np.deg2rad(a)
 return np.column_stack([np.ones(len(a)),np.full(len(a),d)]+[fn(n*t) for n in range(1,k+1) for fn in (np.sin,np.cos)])
for k in (1,2,3):
 X=np.vstack([features(f1[:,0],-1,k),features(r1[:,0],1,k)])
 y=np.r_[f1[:,1],r1[:,1]]
 beta=np.linalg.lstsq(X,y,rcond=None)[0]
 Y=np.vstack([features(f2[:,0],-1,k),features(r2[:,0],1,k)])
 e=np.r_[f2[:,1],r2[:,1]]-Y@beta
 print('harmonics',k,'run1 fit->run2 validation RMSE electrical',np.sqrt(np.mean(e**2)),'max abs',max(abs(e)),'coefficients',beta)
